    {
      "name": "cand_target_mean",
      "op": "mean",
      "inputs": ["call_failure", "subscription_length"],
      "semantic_rationale": "This feature computes the mean target value for each combination of call failure and subscription length, which could provide insights into the churn risk based on these factors.",
